/**
 * Jev decisions as an extension. Mount it and the agent can ask Jev for
 * typed boolean, choice, and score answers, then call `decide` from your
 * own channel hooks and tools before they start a turn or write.
 *
 * ```ts
 * // agent/extensions/jev.ts
 * import jev from "@grok/agent-sdk/extensions/jev";
 *
 * export default jev();
 * ```
 *
 * Contributes `<namespace>__evaluate` plus the `questions` and
 * `gated-write` skills (the namespace is the mount filename). Auth is
 * `TYPESAFE_API_KEY`. The default model is `jev-latest`. Custom tools
 * import `decide`, `above`, and `needsHuman` from this same module. Set
 * `harnessTools` or `skills` to false when the agent should not see those
 * contributions.
 *
 * Hosted deploys allowlist `api.typesafe.ai` for the mounting agent and
 * expect a `TYPESAFE_API_KEY` secret.
 *
 * Experimental: the exports and behavior of this module can change in
 * any release, without a deprecation period.
 */
import * as z from "zod/v4";
import { defineExtension } from "../../extensions.js";
import { DEFAULT_EVALUATION_MODEL, DEFAULT_TYPESAFE_HOST, TYPESAFE_API_KEY_ENV, } from "./lib/evaluate.js";
const config = z
    .object({
    apiKey: z.string().min(1).optional(),
    model: z.string().min(1).optional(),
    harnessTools: z.boolean().default(true),
    skills: z.boolean().default(true),
})
    .prefault({})
    .transform((options) => ({
    apiKey: options.apiKey,
    model: options.model ?? DEFAULT_EVALUATION_MODEL,
    harnessTools: options.harnessTools,
    skills: options.skills,
}));
/** @experimental */
const jev = defineExtension({
    root: import.meta.dirname,
    description: "Ask Jev for typed choice, score, and boolean answers.",
    config,
    contributions: (options) => ({
        tools: options.harnessTools,
        skills: options.skills,
    }),
    // `decide` and `evaluate` in custom tools read the env key even when the
    // mount passes `apiKey`, so the secret is declared unconditionally.
    hosting: () => ({
        egressDomains: [DEFAULT_TYPESAFE_HOST],
        secretNames: [TYPESAFE_API_KEY_ENV],
    }),
});
export { above, DEFAULT_EVALUATION_MODEL, DEFAULT_HUMAN_THRESHOLD, decide, evaluate, needsHuman, } from "./lib/evaluate.js";
export default jev;
